solutionCodeJson.code:
const RISKS = [
 {
  "id": "RK-1",
  "statement": "If key users are not available for elicitation, then requirements may be incomplete.",
  "probability": 0.6,
  "impact": 8
 },
 {
  "id": "RK-2",
  "statement": "If the national e-prescription API changes, then integration may be delayed.",
  "probability": 0.3,
  "impact": 9
 },
 {
  "id": "RK-3",
  "statement": "If the stakeholders disagree on scope, then we may build the wrong product.",
  "probability": 0.5,
  "impact": 10
 },
 {
  "id": "RK-4",
  "statement": "If the UI library is buggy, then screens may need rework.",
  "probability": 0.2,
  "impact": 3
 }
];
function __ok(r) { return r && r.probability >= 0 && r.probability <= 1 && r.impact >= 1 && r.impact <= 10; }
function topRisks(risks, n) {
  return risks.filter(__ok).map(function (r) { return { id: r.id, e: r.probability * r.impact }; })
    .sort(function (a, b) { return b.e - a.e || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0); })
    .slice(0, n).map(function (x) { return x.id; });
}
function worthMitigating(costOfMitigation, risk, costPerImpactPoint) {
  if (!__ok(risk)) return false;
  return costOfMitigation < risk.probability * risk.impact * costPerImpactPoint;
}
